// Types for the wasm-bindgen output in src/engine/ (generated by `npm run wasm`).
declare module "*/engine/frameling.js" {
  export default function init(input?: unknown): Promise<unknown>;
  export class Engine {
    constructor();
    load_demo(): void;
    load_blank(): void;
    load(json: string): void;
    project_json(): string;
    project_view_json(): string;
    media_data(id: string): string | undefined;
    apply(cmd: string, merge?: string): void;
    undo(): boolean;
    redo(): boolean;
    seal(): void;
    can_undo(): boolean;
    can_redo(): boolean;
    is_dirty(): boolean;
    mark_saved(): void;
    catalog(): string;
    add_pack(json: string): string;
    total_frames(): number;
    locate(frame: number): Uint32Array;
    render_scene(scene: number, local: number, width: number, height: number): Uint8Array;
    last_hits(): string;
    camera_at(scene: number, local: number): Float32Array;
    render_frame(frame: number, width: number, height: number): Uint8Array;
    audio_events(): string;
    captions_srt(): string;
    caption_defaults(): string;
    render_item_preview(itemJson: string, width: number, height: number, frame: number): Uint8Array;
    render_background_preview(id: string, width: number, height: number): Uint8Array;
    item_kind(scene: number, id: string): string | undefined;
    posed_item(itemJson: string, frame: number): string;
    parts_catalog(style?: string): string;
    apply_part(lookJson: string, part: string, colorsJson: string): string;
    selected_parts(lookJson: string): string;
    randomize_look(lookJson: string, seed: number, locksJson: string): string;
    part_defs(idsJson: string): string;
    character_pose(scene: number, id: string, local: number): string | undefined;
    pose_keys(pose: string, mask: string, mirror: boolean): string;
    chain_poses(id: string, name: string, stepsJson: string, gap: number, looped: boolean): string;
  }
}
